public async Task<string> GetDataAsync(HttpClient client, string url)
{
    var response = await client.GetAsync(url);     // thread is released while waiting
    response.EnsureSuccessStatusCode();
    return await response.Content.ReadAsStringAsync();
}

public delegate void NotifyHandler(string message);

public class Publisher
{
    public event NotifyHandler OnNotify;

    public void Raise(string msg) => OnNotify?.Invoke(msg);
}

var pub = new Publisher();
pub.OnNotify += msg => Console.WriteLine($"Received: {msg}");
pub.Raise("Hello");

